const glyphs={home:'⌂',subscription:'◇',servers:'◎',connect:'↗',connect_iphone:'▯',connect_android:'▯',connect_windows:'▣',connect_macos:'▢',connect_linux:'⌘',connect_openwrt:'⌁',plans:'＋',plan_1:'1',plan_3:'3',plan_6:'6',plan_12:'12',payment_success:'✓',payments:'≋',network:'◉',referrals:'↗',profile:'◌',settings:'⚙',support:'?',};
const names={home:'Главная',subscription:'Подписка',servers:'Серверы',connect:'Подключение',connect_iphone:'Инструкция · iPhone',connect_android:'Инструкция · Android',connect_windows:'Инструкция · Windows',connect_macos:'Инструкция · macOS',connect_linux:'Инструкция · Linux',connect_openwrt:'Инструкция · OpenWrt',plans:'Продление',plan_1:'1 месяц · 199 ₽',plan_3:'3 месяца · 597 ₽',plan_6:'6 месяцев · 1 194 ₽',plan_12:'12 месяцев · 2 388 ₽',payment_success:'Оплата прошла',payments:'Платежи',network:'Состояние сети',referrals:'Рефералы',profile:'Профиль',settings:'Настройки',support:'Поддержка'};
const order=Object.keys(names);const screens=window.TG_UI_SCREENS||{};
const nav=document.querySelector('#screen-nav'),content=document.querySelector('#message-content'),title=document.querySelector('#screen-title'),chat=document.querySelector('#chat-body');
function switchTo(key){if(!screens[key])return;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.screen===key));title.textContent=names[key]||screens[key].label;content.replaceChildren(...screens[key].rich_message.blocks.map(renderBlock));chat.scrollTop=0;}
function renderBlock(block){let el;if(block.type==='heading'){el=document.createElement(block.size<=2?'h2':'h3');el.textContent=plain(block.text)}else if(block.type==='paragraph'){el=document.createElement('p');el.textContent=plain(block.text);if(/обновлено|Период|Выберите устройство|Использовано/.test(el.textContent))el.className='subtle'}else if(block.type==='divider'){el=document.createElement('hr')}else if(block.type==='footer'){el=document.createElement('div');el.className='rich-footer';el.textContent=plain(block.text)}else if(block.type==='table'){el=renderTable(block)}else if(block.type==='details'){el=document.createElement('details');const s=document.createElement('summary');s.textContent=plain(block.summary);el.append(s,...(block.blocks||[]).map(renderBlock))}else if(block.type==='list'){el=document.createElement(block.is_ordered?'ol':'ul');for(const item of block.items||[]){const li=document.createElement('li');li.value=Number(item.value)||undefined;li.append(...(item.blocks||[]).map(renderBlock));el.append(li)}}else if(block.type==='expandable_blockquote'){el=document.createElement('details');el.className='rich-quote';const s=document.createElement('summary');s.textContent=plain(block.credit||'Подробнее');const p=document.createElement('p');p.textContent=plain(block.text);el.append(s,p)}else if(block.type==='buttons'){el=document.createElement('div');el.className='button-row';for(const b of block.buttons||[]){const button=document.createElement('button');button.type='button';button.className='rich-button '+(b.style||'');button.textContent=plain(b.text);button.addEventListener('click',()=>{if(b.callback_data)activate(b.callback_data);else if(b.copy_text?.text)notify('Ссылка готова к копированию');else if(b.url)notify('Открытие внешней ссылки доступно в Telegram')});el.append(button)}}else{el=document.createElement('p');el.textContent=plain(block.text||'')}return el}
function renderTable(block){const table=document.createElement('table');if(block.is_striped)table.classList.add('striped');for(const row of block.cells||[]){const tr=document.createElement('tr');for(const cell of row){const tag=cell.is_header?'th':'td',td=document.createElement(tag);td.textContent=plain(cell.text||'');if(cell.colspan>1)td.colSpan=cell.colspan;if(cell.align)td.style.textAlign=cell.align;tr.append(td)}table.append(tr)}return table}
function plain(value){if(typeof value==='string')return value;if(Array.isArray(value))return value.map(plain).join('');if(value&&typeof value==='object')return value.text?plain(value.text):'';return String(value??'')}
function notify(text){document.querySelector('.toast')?.remove();const toast=document.createElement('div');toast.className='toast';toast.textContent=text;document.querySelector('.phone').append(toast);setTimeout(()=>toast.remove(),2200)}
function activate(action=''){if(action==='ui:home')return switchTo('home');if(action==='ui:subscription')return switchTo('subscription');if(action==='ui:servers')return switchTo('servers');if(action==='ui:connect')return switchTo('connect');if(action==='ui:plans')return switchTo('plans');if(action==='ui:payments')return switchTo('payments');if(action==='ui:referrals')return switchTo('referrals');if(action==='ui:profile')return switchTo('profile');if(action==='ui:settings')return switchTo('settings');if(action==='ui:support')return switchTo('support');if(action==='ui:demo:pay'||action.startsWith('ui:demo:pay:')||action.startsWith('buy:'))return switchTo('payment_success');if(action.startsWith('ui:plan:')){const id=action.split(':').at(-1),n=id.match(/(\d+)$/)?.[1];return switchTo('plan_'+(n||'1'))}if(action.startsWith('ui:connect:')){const device=action.split(':').at(-1);return switchTo('connect_'+device)}if(action.startsWith('ui:demo:')){const old=document.querySelector('.toast');old?.remove();const toast=document.createElement('div');toast.className='toast';toast.textContent='Действие показано в прототипе · backend не подключён';document.querySelector('.phone').append(toast);setTimeout(()=>toast.remove(),2200);return}if(action==='ui:network')return switchTo('network')}
for(const key of order){const a=document.createElement('a');a.href='#'+key;a.className='nav-item';a.dataset.screen=key;a.innerHTML='<span class="nav-icon">'+glyphs[key]+'</span><span>'+names[key]+'</span>';a.addEventListener('click',event=>{event.preventDefault();switchTo(key)});nav.append(a)}switchTo('home');
